const description: { en: string; ja: string } = {"en":"Three broad sake flasks stand one above two, the upper one in front, the lower ones' caps beside its pouch.","ja":"幅の広い瓶子を三つ、一つを上に二つを下に置きます。上の瓶子が手前で、下の二つの口覆いがその胴の脇に来ます。"};

